import React from "react";

const CustomTable = ({ cols, rows, visibleCols = {} }) => {
  const getVisible = (key) => visibleCols[key] ?? true;

  return (
    <div className="overflow-x-auto">
      <table className="min-w-full text-left border border-gray-200 rounded-xl overflow-hidden">
        <thead className="sticky top- z-10 bg-[#E1D5C9] text-[#292929]">
          <tr>
            {cols.map(
              (col, i) =>
                getVisible(col.key) && (
                  <th
                    key={i}
                    className={`px-4 py-3 ${i === 0 ? "rounded-tl-xl" : ""} ${
                      i === cols.length - 1 ? "rounded-tr-xl" : ""
                    }`}
                  >
                    {col.label}
                  </th>
                )
            )}
            <th className="px-4 py-3 rounded-tr-xl">Actions</th>
          </tr>
        </thead>

        <tbody>
          {rows.map((row, rIndex) => (
            <tr
              key={rIndex}
              className={`${
                rIndex % 2 === 0 ? "bg-white" : "bg-[#F5EFEB]"
              } text-[#292929]`}
            >
              {cols.map(
                (col, cIndex) =>
                  getVisible(col.key) && (
                    <td
                      key={cIndex}
                      className={`px-4 py-3 ${
                        cIndex === 0 ? "rounded-bl-xl" : ""
                      } ${cIndex === cols.length - 1 ? "rounded-br-xl" : ""}`}
                    >
                      {col.render
                        ? col.render(row[col.key], row)
                        : row[col.key]}
                    </td>
                  )
              )}
              <td className="px-4 py-3">
                <div className="flex gap-3">
                  {row.actions || <span className="text-gray-400">—</span>}
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default CustomTable;
